import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Filter out near-duplicates based on correlation
    ids = list(feats.ids)
    correlations = {}
    for i, id1 in enumerate(ids):
        for j, id2 in enumerate(ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feats.column(id1)], feats.x[:, feats.column(id2)])[0,1]) >= 0.6:
                correlations[id1] = id2

    # Remove near-duplicates (keep first occurrence)
    unique_ids = []
    seen = set()
    for id in ids:
        if id not in seen:
            unique_ids.append(id)
            seen.add(id)
            if id in correlations:
                seen.add(correlations[id])

    # Calculate effect sizes using t-tests
    effects = []
    for id in unique_ids:
        col = feats.column(id)
        y0 = feats.x[feats.y == 0, col]
        y1 = feats.x[feats.y == 1, col]
        t_stat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        effects.append((id, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates
    candidates = [id for id, _ in effects[:MAX_DRIVERS]]

    # If no strong effect, return empty design
    if not candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check if any pair has high correlation
    products = []
    for i, id1 in enumerate(candidates):
        for id2 in candidates[i+1:]:
            if abs(np.corrcoef(feats.x[:, feats.column(id1)], feats.x[:, feats.column(id2)])[0,1]) >= 0.6:
                products.append((id1, id2))

    # Return design with drivers and their columns
    return Design(
        drivers=tuple(candidates),
        columns=tuple(candidates),
        products=tuple(products),
        loadings={id: 1.0 for id in candidates}
    )

